import{_ as o,o as n,c as a,ah as s}from"./chunks/framework.BJPOZ--0.js";const r="/projects/NexArm/en/ros-version/assets/image1.DVw1dmvl.png",l="/projects/NexArm/en/ros-version/assets/image2.FwJU-WfO.png",c="/projects/NexArm/en/ros-version/assets/image3.DehcltIO.png",p="/projects/NexArm/en/ros-version/assets/image4.CwYVHRrx.png",d="/projects/NexArm/en/ros-version/assets/image5.D67lDVhD.png",g="/projects/NexArm/en/ros-version/assets/image6.BoXE-c7E.png",m="/projects/NexArm/en/ros-version/assets/image7.BMfPOL7N.png",h="/projects/NexArm/en/ros-version/assets/image8.C4mWuoOO.GIF",u="/projects/NexArm/en/ros-version/assets/image9.Br5X0Nef.png",f="/projects/NexArm/en/ros-version/assets/image10.WluxV7cK.png",y="/projects/NexArm/en/ros-version/assets/image12.YcKYq7HO.png",b="/projects/NexArm/en/ros-version/assets/image13.D0UojVh6.png",v="/projects/NexArm/en/ros-version/assets/image14.CJ81EfAM.png",w="/projects/NexArm/en/ros-version/assets/image15.DEPUn7TN.png",A="/projects/NexArm/en/ros-version/assets/image16.bmeRv0kc.png",x="/projects/NexArm/en/ros-version/assets/image17.BVq22dAH.png",k="/projects/NexArm/en/ros-version/assets/image18.DPCOrZlT.png",C="/projects/NexArm/en/ros-version/assets/image19.C3QtkC3K.png",_="/projects/NexArm/en/ros-version/assets/image20.CQt6DnTP.png",q="/projects/NexArm/en/ros-version/assets/image21.BYeEl2Wj.png",N="/projects/NexArm/en/ros-version/assets/image22.CNMwh1Bh.png",i="data:image/png;base64,",B="/projects/NexArm/en/ros-version/assets/image2.BxFe545J.png",E="/projects/NexArm/en/ros-version/assets/image3.B8SjBBiI.png",I="/projects/NexArm/en/ros-version/assets/image4.BLBGmPsS.png",P="/projects/NexArm/en/ros-version/assets/image5.AhYpmRlh.png",S="/projects/NexArm/en/ros-version/assets/image6.BsTsp8A_.png",z="/projects/NexArm/en/ros-version/assets/image7.By2NCO6A.png",T="/projects/NexArm/en/ros-version/assets/image8.C2G0uHHo.png",R="/projects/NexArm/en/ros-version/assets/image9.DRGx8HuT.png",D="/projects/NexArm/en/ros-version/assets/image10.D1w0rp19.png",O="/projects/NexArm/en/ros-version/assets/image11.DT0EiSq6.png",L="/projects/NexArm/en/ros-version/assets/image12.BCHSGQxc.png",F="/projects/NexArm/en/ros-version/assets/image13.DKpbjNpX.png",G="/projects/NexArm/en/ros-version/assets/image14.BS91yX3Y.png",U="/projects/NexArm/en/ros-version/assets/image15.C5fhYkkH.png",Q="/projects/NexArm/en/ros-version/assets/image16.BX-tHm-G.png",t="data:image/png;base64,",M="/projects/NexArm/en/ros-version/assets/image18.BhhcqEj5.png",j="/projects/NexArm/en/ros-version/assets/image19.BPiB6Zzf.png",J="/projects/NexArm/en/ros-version/assets/image20.RMXHAqtF.png",X="/projects/NexArm/en/ros-version/assets/image21.CGe-X7d0.png",ie=JSON.parse('{"title":"6. Deep Learning Application","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6. Deep Learning Application.md","filePath":"docs/6. Deep Learning Application.md"}'),H={name:"docs/6. Deep Learning Application.md"};function V(W,e,Y,Z,K,$){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_6-deep-learning-application" tabindex="-1">6. Deep Learning Application <a class="header-anchor" href="#_6-deep-learning-application" aria-label="Permalink to &quot;6. Deep Learning Application&quot;">​</a></h1><h2 id="_6-1-introduction-to-machine-learning" tabindex="-1">6.1 Introduction to Machine Learning <a class="header-anchor" href="#_6-1-introduction-to-machine-learning" aria-label="Permalink to &quot;6.1 Introduction to Machine Learning&quot;">​</a></h2><h3 id="_6-1-1-preface" tabindex="-1">6.1.1 Preface <a class="header-anchor" href="#_6-1-1-preface" aria-label="Permalink to &quot;6.1.1 Preface&quot;">​</a></h3><p>Artificial Intelligence, abbreviated as AI, is a new technical science that researches and develops theories, methods, technologies, and application systems for simulating, extending, and expanding human intelligence.</p><p>Artificial intelligence encompasses machine learning, computer vision, natural language processing, and deep learning. Among them, machine learning is a sub-field of artificial intelligence, whereas deep learning is a category of machine learning.</p><p>Since its inception, theories and technologies of artificial intelligence have matured daily, and application domains have expanded continuously, gradually becoming an independent branch.</p><h3 id="_6-1-2-what-is-machine-learning" tabindex="-1">6.1.2 What is Machine Learning <a class="header-anchor" href="#_6-1-2-what-is-machine-learning" aria-label="Permalink to &quot;6.1.2 What is Machine Learning&quot;">​</a></h3><p>Machine learning is the core of artificial intelligence and the fundamental path enabling machines to possess intelligence. It is a multi-disciplinary crossfield involving probability theory, statistics, approximation theory, convex analysis, algorithm complexity theory, and other disciplines.</p><p>Deep learning is a new domain of machine learning, mainly researching how computers acquire new knowledge or skills by simulating or implementing human learning behaviors, reorganizing existing knowledge structures to continuously improve their performance. From a practical perspective, it means utilizing data to train models and using models to make predictions.</p><p>Taking AlphaGo as an example, it is the first artificial intelligence robot to defeat a professional human Go player and the first to beat a Go world champion. The main working principle of AlphaGo is deep learning, which means learning intrinsic patterns and representation hierarchies of sample data to acquire information.</p><h3 id="_6-1-3-classification-of-machine-learning" tabindex="-1">6.1.3 Classification of Machine Learning <a class="header-anchor" href="#_6-1-3-classification-of-machine-learning" aria-label="Permalink to &quot;6.1.3 Classification of Machine Learning&quot;">​</a></h3><p>Machine learning is divided into supervised learning and unsupervised learning, where the difference lies in whether classifications or patterns of the dataset are known beforehand.</p><ul><li><strong>Supervised Learning</strong></li></ul><p>Supervised learning refers to providing a dataset to the algorithm alongside correct answers, allowing the machine to utilize the dataset to learn calculation methods for correct answers. Supervised learning is the most common form of machine learning.</p><p>Taking image recognition as an example, a large number of dog images are provided and tagged with the label &quot;dog&quot;, where this label serves as the <strong>correct answer</strong>. Through extensive learning, the machine learns to identify dogs in new images.</p><ul><li><strong>Unsupervised Learning</strong></li></ul><p>Unsupervised learning refers to providing a dataset to the algorithm without giving correct answers. All data items are treated identically, and the machine extracts underlying structural relationships from the dataset.</p><p>Taking image classification as an example, a large number of cat and dog images are provided without adding labels to the images. Through learning, the machine divides images into two categories, namely cat images and dog images.</p><h2 id="_6-2-introduction-to-machine-learning-libraries" tabindex="-1">6.2 Introduction to Machine Learning Libraries <a class="header-anchor" href="#_6-2-introduction-to-machine-learning-libraries" aria-label="Permalink to &quot;6.2 Introduction to Machine Learning Libraries&quot;">​</a></h2><p>Machine learning frameworks exist in large numbers, with common frameworks including PyTorch, TensorFlow, MXNet, and PaddlePaddle.</p><h3 id="_6-2-1-pytorch" tabindex="-1">6.2.1 PyTorch <a class="header-anchor" href="#_6-2-1-pytorch" aria-label="Permalink to &quot;6.2.1 PyTorch&quot;">​</a></h3><p>Torch is an open-source machine learning framework based on the BSD License, supporting heavy multi-dimensional array operations, and is widely applied in the field of machine learning. PyTorch is a machine learning framework based on Torch. Compared to Torch, PyTorch is more flexible, supports dynamic computation graphs, and provides a Python interface.</p><p>Different from the static computation graphs of TensorFlow, the computation graphs of PyTorch are dynamic, allowing real-time changes to the computation graph according to computation requirements, as well as enabling developers to accelerate tensor computations via GPUs, create dynamic computation graphs, and automatically compute gradients.</p><h3 id="_6-2-2-tensorflow" tabindex="-1">6.2.2 TensorFlow <a class="header-anchor" href="#_6-2-2-tensorflow" aria-label="Permalink to &quot;6.2.2 TensorFlow&quot;">​</a></h3><p>TensorFlow is an open-source machine learning framework that can be used to quickly construct neural networks while conveniently carrying out network training, evaluation, and saving. It implements machine learning and deep learning concepts in the simplest manner. It combines computational algebra with optimization techniques to facilitate evaluation of numerous mathematical expressions.</p><p>TensorFlow can run on machines of different types and sizes. This makes TensorFlow useful on supercomputers, embedded systems, or any intermediate computers between them. TensorFlow can utilize CPUs, GPUs, or both simultaneously. Compared to other machine learning frameworks, the TensorFlow framework is the most suitable machine learning framework for industrial deployment, meaning TensorFlow is highly suitable for production environment applications.</p><h3 id="_6-2-3-paddlepaddle" tabindex="-1">6.2.3 PaddlePaddle <a class="header-anchor" href="#_6-2-3-paddlepaddle" aria-label="Permalink to &quot;6.2.3 PaddlePaddle&quot;">​</a></h3><p>PaddlePaddle is a deep learning framework proposed by Baidu. Based on years of deep learning technology research and business applications at Baidu, it integrates core deep learning training and inference frameworks, basic model libraries, end-to-end development kits, and rich tool components into one platform, serving as the first self-developed, feature-rich, open-source industrial-grade deep learning platform in China.</p><p>In recent years, deep learning has demonstrated outstanding performance in many machine learning fields, with wide applications in image recognition, speech recognition, natural language processing, robotics, online advertising delivery, automated medical diagnosis, and finance.</p><h3 id="_6-2-4-mxnet" tabindex="-1">6.2.4 MXNet <a class="header-anchor" href="#_6-2-4-mxnet" aria-label="Permalink to &quot;6.2.4 MXNet&quot;">​</a></h3><p>MXNet is an excellent deep learning framework. Currently, it includes numerous language interfaces such as Python, C++, Scala, and R. It possesses dataflow graphs similar to Theano and TensorFlow, provides good configurations for multi-GPU setups, features higher-level model construction blocks similar to Lasagne and Blocks, and can run on almost any hardware imaginable, including mobile phones.</p><p>MXNet is a deep learning framework designed to improve efficiency and flexibility. Acceleration libraries like MXNet provide powerful tools to assist developers in leveraging the full power of GPUs and cloud computing. MXNet can be distributed across dynamic cloud architectures via distributed parameter servers and achieve near-linear scaling through multiple GPUs or CPUs.</p><h2 id="_6-3-yolo-model" tabindex="-1">6.3 YOLO Model <a class="header-anchor" href="#_6-3-yolo-model" aria-label="Permalink to &quot;6.3 YOLO Model&quot;">​</a></h2><h3 id="_6-3-1-overview-of-yolo-series-models" tabindex="-1">6.3.1 Overview of YOLO Series Models <a class="header-anchor" href="#_6-3-1-overview-of-yolo-series-models" aria-label="Permalink to &quot;6.3.1 Overview of YOLO Series Models&quot;">​</a></h3><ul><li><strong>YOLO Series</strong></li></ul><p>The YOLO series, standing for You Only Look Once, is a single-stage, deep-learning-based regression method.</p><p>Before the appearance of YOLOv1, the R-CNN series algorithms dominated the target detection field with high detection accuracy, but their two-stage network structures prevented detection speed from meeting real-time requirements.</p><p>Addressing this issue, YOLO was born, whose core concept is to redefine target detection as a regression problem, using the whole image as network input to directly regress bounding box positions and corresponding categories at the output layer. Compared with traditional target detection methods, YOLO offers advantages such as fast detection speed and high mean average precision.</p><ul><li><strong>YOLO26</strong></li></ul><p>YOLO26 is a new generation of real-time target detection model launched by Ultralytics, optimized on the basis of previous YOLO versions, with significant enhancements in detection speed and precision.</p><p><strong>YOLO26 Core Summary</strong></p><ol><li><p><strong>Architecture Simplification</strong>: Remove Distribution Focal Loss <strong>DFL</strong>, simplify bounding box regression, and enhance export compatibility.</p></li><li><p><strong>End-to-End Inference</strong>: Adopt NMS-free design, outputting detection results directly to reduce latency and deployment complexity.</p></li><li><p><strong>Training Enhancement</strong>: Introduce Progressive Loss Balancing <strong>ProgLoss</strong> and Small-Target-Aware Label Allocation <strong>STAL</strong> to boost small target detection stability.</p></li><li><p><strong>Optimizer Innovation</strong>: Use the MuSGD optimizer, combining the advantages of SGD and Muon to accelerate model convergence.</p></li><li><p><strong>Multi-Task Support</strong>: Unified framework supporting detection, instance segmentation, pose estimation, oriented detection, and classification.</p></li><li><p><strong>Edge Optimization</strong>: Support FP16 and INT8 quantization, achieving low-latency real-time inference on Jetson and other devices.</p></li><li><p><strong>Performance Output</strong>: Achieve high precision on benchmarks such as COCO, with CPU inference speed increased by up to 43 percent compared to the previous generation.</p></li></ol><h3 id="_6-3-2-yolo26-model-structure" tabindex="-1">6.3.2 YOLO26 Model Structure <a class="header-anchor" href="#_6-3-2-yolo26-model-structure" aria-label="Permalink to &quot;6.3.2 YOLO26 Model Structure&quot;">​</a></h3><ul><li><strong>Component Elements</strong></li></ul><ol><li>Convolutional Layer: Feature Extraction</li></ol><p>Convolution refers to the impact of an event occurring across multiple past time points, performing or undergoing the same action, on the current state of an event. Convolution can be decomposed into two parts, namely &quot;folding&quot; and &quot;integration&quot;.</p><p>&quot;Folding&quot; can be understood as reversing data, while &quot;integration&quot; can be understood as accumulating the impact of past data on current data. Reversing data builds relationships among data items, facilitating corresponding reference for calculating accumulated impact amounts.</p><img loading="lazy" height="274" width="1264" class="common_img" src="'+r+'" style="width:800px;"><p>In YOLO26, the data to process consists of images. Images are two-dimensional in computer vision, and the corresponding convolution belongs to two-dimensional convolution. The purpose of two-dimensional convolution is to extract features in images. When performing two-dimensional convolution, understanding the convolution kernel is essential.</p><p>A convolution kernel is a unit area for performing convolution calculations each time. Unit areas of convolution kernels use pixels as units, and integration is performed on pixels within each area during calculation. Generally, convolution is conducted by sliding the convolution kernel, and kernel size requires manual configuration.</p><p>When performing convolution calculation, the outer periphery of the image remains unchanged or expands by arbitrary pixels according to desired effects, and convolution results are re-inserted into corresponding positions in the image.</p><p>Taking an image with a resolution of 6 by 6 as an example, expand it to a 7 by 7 image first, and substitute the image into the convolution kernel for calculation. Finally, fill the data into a blank image with a resolution of 6 by 6.</p><img loading="lazy" height="358" width="1054" class="common_img" src="'+l+'" style="width:800px;"><img loading="lazy" height="739" width="703" class="common_img" src="'+c+'" style="width:800px;"><ol start="2"><li>Pooling Layer: Feature Amplification</li></ol><p>Pooling layers, also called downsampling layers, are generally used alongside convolutional layers. After convolution computation completes, pooling layers perform further sampling operations on features. Pooling is divided into various types, such as global pooling, average pooling, and max pooling. Different pooling types yield different effects.</p><p>For ease of comprehension, max pooling is used here as an example. Before understanding max pooling, filters must be understood, which, like convolution kernels, require manual area setting. Filters slide during computation to filter pixels within the area pixel by pixel.</p><img loading="lazy" height="309" width="701" class="common_img" src="'+p+'" style="width:800px;"><p>Max pooling can be understood as retaining the most prominent features while removing remaining features. Taking an image with a resolution of 6 by 6 as an example, when pooling begins, use a 2 by 2 filter to calculate on the original image, obtaining a new image.</p><img loading="lazy" height="789" width="862" class="common_img" src="'+d+'" style="width:800px;"><ol start="3"><li>Upsampling Layer: Dimension Restoration</li></ol><p>Upsampling can be understood as &quot;unpooling&quot;. Images shrink after pooling. Performing upsampling restores images to their original dimensions. However, only dimensions are restored, while post-pooling features change accordingly.</p><p>Taking an image with a resolution of 6 by 6 as an example, when upsampling begins, use a 3 by 3 filter to calculate on the original image to obtain a new image.</p><img loading="lazy" height="750" width="787" class="common_img" src="'+g+'" style="width:800px;"><ol start="4"><li>Batch Normalization Layer: Data Organization</li></ol><p>Batch normalization operations on data refer to rearranging data neatly. Their practical function is to reduce model computation difficulty and allow data to map better into activation functions.</p><p>Batch normalization processing reduces feature loss rates after each calculation, allowing more features to be retained for subsequent calculations. After multiple calculations, model sensitivity toward data improves accordingly.</p><img loading="lazy" height="195" width="775" class="common_img" src="'+m+'" style="width:800px;"><ol start="5"><li>RELU Layer: Activation Function</li></ol><p>Adding activation functions during model construction increases model non-linearity. Without activation functions, each layer is equivalent to matrix multiplication. The output of each layer is a linear function of input from the upper layer, meaning no matter how many layers a neural network has, the output remains a linear combination of input, preventing constructed models from changing according to practical situations.</p><p>Activation functions exist in many types, with common ones including RELU, TANH, and SIGMOID. RELU is used as an example here. The Rectified Linear Unit function is a piecewise function that replaces all values less than 0 with 0 while keeping positive values unchanged.</p><img loading="lazy" height="392" width="536" class="common_img" src="'+h+'" style="width:600px;"><ol start="6"><li>ADD Layer: Tensor Addition</li></ol><p>Features are divided into prominent features and non-prominent features. The function of the ADD layer is to add tensors of features together, achieving feature enhancement effects for prominent features.</p><img loading="lazy" height="316" width="836" class="common_img" src="'+u+'" style="width:800px;"><ol start="7"><li>Concat Layer: Tensor Concatenation</li></ol><p>The function of the Concat layer is to concatenate tensors of features, thereby concatenating features extracted through different methods together to preserve more features.</p><img loading="lazy" height="1536" width="1024" class="common_img" src="'+f+'" style="width:600px;"><ul><li><strong>Composite Elements</strong></li></ul><p>When building models, using only the basic layers mentioned above to construct functions can easily result in verbose code, chaotic structures, and unclear layering. Organizing basic elements into various units for invocation effectively improves model coding efficiency.</p><ol><li>Convolutional Unit</li></ol><p>A convolutional unit consists of a convolutional layer, a batch normalization layer, and an activation function. Convolution is performed first, followed by batch normalization, and finally activation via the activation function.</p><img loading="lazy" height="293" width="821" class="common_img" src="'+y+'" style="width:800px;"><ol start="2"><li>Focus Unit</li></ol><p>First, divide the input image into multiple large regions, and then concatenate small images located at identical positions within each large region to decompose the input image into several images. Finally, perform initial sampling on images via a convolutional unit.</p><p>As shown below, taking an image with a resolution of 6 by 6 as an example, setting one large region as 2 by 2 decomposes the image into 9 large regions, with each large region containing 4 small images.</p><p>Concatenating small images located at Position 1 within each large region yields a 3 by 3 image. Small images at other positions are concatenated in the same way, eventually decomposing the original 6 by 6 image into four 3 by 3 images.</p><img loading="lazy" height="418" width="1055" class="common_img" src="'+b+'" style="width:800px;"><ol start="3"><li>Residual Unit</li></ol><p>The function of a residual unit is to enable the model to learn subtle changes in images. Its structure is relatively simple, implemented by superimposing data obtained through two paths.</p><p>The first path features two convolutional units to sample the image, while the second path does not place convolutional units for sampling, using the original image directly instead. Finally, data from the first path is superimposed onto the second path.</p><img loading="lazy" height="287" width="963" class="common_img" src="'+v+'" style="width:800px;"><img loading="lazy" height="376" width="1060" class="common_img" src="'+w+'" style="width:800px;"><ol start="4"><li>Composite Convolutional Unit</li></ol><p>In YOLO models, the composite convolutional unit is characterized primarily by customizability of convolutional units according to requirements. Composite convolutional units are also implemented via data superposition from two paths.</p><p>The first path has only one convolutional layer for sampling, while the second path features <code>2x+1</code> convolutional units and one convolutional layer for sampling. After sampling and concatenation, data is organized via batch normalization and passed through an activation function. Finally, one convolutional unit is used for sampling.</p><img loading="lazy" height="750" width="522" class="common_img" src="'+A+'" style="width:600px;"><ol start="5"><li>Composite Residual Convolutional Unit</li></ol><p>Composite residual convolutional units replace <code>2x</code> convolutional units inside composite convolutional units with <code>x</code> residual units. In YOLO26, composite residual units feature customizability of residual units according to requirements.</p><img loading="lazy" height="750" width="522" class="common_img" src="'+x+'" style="width:600px;"><ol start="6"><li>Composite Pooling Unit</li></ol><p>Output data of the convolutional unit is fed into three max pooling layers separately, with another copy kept unprocessed. Subsequently, data from the four routes is concatenated, and the result is fed into a convolutional unit. Processing data with composite pooling units significantly amplifies features of the original data.</p><img loading="lazy" height="705" width="743" class="common_img" src="'+k+'" style="width:600px;"><h3 id="_6-3-3-yolo26-execution-workflow" tabindex="-1">6.3.3 YOLO26 Execution Workflow <a class="header-anchor" href="#_6-3-3-yolo26-execution-workflow" aria-label="Permalink to &quot;6.3.3 YOLO26 Execution Workflow&quot;">​</a></h3><p>This section explains model workflow execution using prior boxes, prediction boxes, and anchor boxes used in YOLO26.</p><ul><li><strong>Prior Box</strong></li></ul><p>When feeding images into the model, target recognition regions on images need to be provided, and prior boxes are boxes used to mark target recognition regions on images in advance.</p><img loading="lazy" height="588" width="1039" class="common_img" src="'+C+'" style="width:800px;"><ul><li><strong>Prediction Box</strong></li></ul><p>Prediction boxes require no manual configuration, as they are output results of the model. When the first batch of training data is fed into the model, prediction boxes are generated automatically. Locations where objects of the same category appear with higher frequency are set as center points of prediction boxes.</p><img loading="lazy" height="590" width="1039" class="common_img" src="'+_+'" style="width:800px;"><ul><li><strong>Anchor Box</strong></li></ul><p>After prediction boxes are generated, deviations in size and location may occur. The function of anchor boxes is to correct the size and location of prediction boxes.</p><p>Locations where anchor boxes are generated are determined by prediction boxes. To influence locations of subsequent prediction box generation, anchor boxes are generated at relative center positions of existing prediction boxes.</p><img loading="lazy" height="586" width="1039" class="common_img" src="'+q+'" style="width:800px;"><ul><li><strong>Implementation Workflow</strong></li></ul><p>After completing dataset labeling, prior boxes appear on images. Subsequently, when image data is fed into the model, the model generates prediction boxes according to prior box locations. After prediction boxes are generated, anchor boxes are generated accordingly. Finally, the weights of this training session are updated in the model.</p><p>Newly generated prediction boxes are influenced by anchor boxes generated previously. By repeating the above operations, size and position deviations of prediction boxes gradually disappear until overlapping with prior boxes.</p><img loading="lazy" height="181" width="969" class="common_img" src="'+N+'" style="width:800px;"><h2 id="_6-4-yolo26-model-training" tabindex="-1">6.4 YOLO26 Model Training <a class="header-anchor" href="#_6-4-yolo26-model-training" aria-label="Permalink to &quot;6.4 YOLO26 Model Training&quot;">​</a></h2><h3 id="_6-4-1-image-collection-and-labeling" tabindex="-1">6.4.1 Image Collection and Labeling <a class="header-anchor" href="#_6-4-1-image-collection-and-labeling" aria-label="Permalink to &quot;6.4.1 Image Collection and Labeling&quot;">​</a></h3><p>Since training YOLO models requires large amounts of data, collecting and labeling data must be performed first to prepare for subsequent model training.</p><ul><li><strong>Image Collection</strong></li></ul><ol><li><p>Power on the robot and connect it to the remote control software VNC.</p></li><li><p>Click the icon <img loading="lazy" height="38" width="46" class="inline-icon" src="'+i+'" style="width:30px;"> on the system desktop to open the command line terminal.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><ol start="3"><li>Enter the command to start the depth camera service.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch peripherals depth_camera.launch.py</span></span></code></pre></div><ol start="4"><li>Open a new command line terminal and enter the command to create a new directory for storing datasets.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p ~/my_data</span></span></code></pre></div><ol start="5"><li>Then enter the command to launch the image collection tool.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/software/collect_picture &amp;&amp; python3 main.py</span></span></code></pre></div><img loading="lazy" height="649" width="701" class="common_img" src="'+B+'" style="width:600px;"><p>The <strong>save number</strong> in the upper left corner indicates the image ID, representing which image is saved, while <strong>existing</strong> indicates the quantity of saved images.</p><ol start="6"><li><p>Click to select, modifying the saving path to the created directory folder.</p><img loading="lazy" height="76" width="536" class="common_img" src="'+E+'" style="width:800px;"></li><li><p>After selecting the corresponding directory, click <strong>Choose</strong>:</p><img loading="lazy" height="397" width="563" class="common_img" src="'+I+'" style="width:800px;"></li><li><p>Place target recognition contents within the camera field of view, click <strong>Save (space)</strong> button or press <strong>Space</strong> to save current camera frame.</p><img loading="lazy" height="650" width="702" class="common_img" src="'+P+'" style="width:800px;"></li><li><p>After clicking <strong>Save (space)</strong> or pressing <strong>Space</strong>, a <strong>JPEGImages</strong> folder for saving images automatically generates under directory <strong>/home/ubuntu/my_data</strong>.</p><img loading="lazy" height="650" width="702" class="common_img" src="'+S+'" style="width:800px;"></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>To enhance model reliability, photograph target recognition contents from different distances, rotation angles, and tilt angles.</strong></p></div><ol start="10"><li>After completing image collection, click <strong>Exit</strong> button to close this tool.</li></ol><img loading="lazy" height="88" width="682" class="common_img" src="'+z+'" style="width:800px;"><ol start="11"><li>Open terminal and enter command to view saved images.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/my_data/JPEGImages &amp;&amp; ls</span></span></code></pre></div><img loading="lazy" height="20" width="751" class="common_img" src="'+T+'" style="width:800px;"><ol start="12"><li>Then press key combination <strong>Ctrl+C</strong> in all open command line terminals to exit, completing image collection steps.</li></ol><ul><li><strong>Image Labeling</strong></li></ul><p>After collecting images, images must be labeled. Image labeling is essential for functional datasets because it informs the training model which categories important image parts belong to, allowing recognition of these categories in new, unseen images later.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Command inputs require strict case sensitivity, and Tab key can be used to complete keywords.</strong></p></div><ol><li>Open command terminal, enter command, and launch image labeling software.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ~/software/roLabelImg/roLabelImg.py</span></span></code></pre></div><img loading="lazy" height="24" width="801" class="common_img" src="'+R+'" style="width:800px;"><ol start="2"><li><p>After opening software, click <strong>File</strong> in upper left corner, select <strong>Open Dir</strong>, choose directory containing collected images, and click <strong>Choose</strong>.</p><img loading="lazy" height="409" width="551" class="common_img" src="'+D+'" style="width:600px;"><img loading="lazy" height="400" width="565" class="common_img" src="'+O+'" style="width:600px;"></li><li><p>Click <strong>File</strong> in upper left corner, select <strong>Change default saved Annotation dir</strong> to change saving path, selecting <strong>Annotations</strong> directory under <strong>my_data</strong> folder.</p><img loading="lazy" height="207" width="397" class="common_img" src="'+L+'" style="width:600px;"><img loading="lazy" height="400" width="563" class="common_img" src="'+F+'" style="width:600px;"></li><li><p>Click <strong>View</strong> in upper left corner and select <strong>Advanced Mode</strong> to enable rotation labeling functionality.</p><img loading="lazy" height="238" width="387" class="common_img" src="'+G+'" style="width:600px;"></li><li><p>Shortcut key <strong>e</strong> represents labeling rotating targets, <strong>d</strong> represents next image, <strong>a</strong> represents previous image, <strong>c</strong> represents slight clockwise rotation, <strong>x</strong> represents slight counterclockwise rotation, <strong>v</strong> represents large clockwise rotation, and <strong>z</strong> represents large counterclockwise rotation. After labeling each image, click <strong>save</strong> icon on left side to save.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Always use keyboard keys C and X for rotation to align rectangle box angles with object borders, otherwise subsequent recognition will be affected.</strong></p></div><img loading="lazy" height="693" width="920" class="common_img" src="'+U+'" style="width:700px;"></li><li><p>Name category of target recognition contents in pop-up window, named after labeled objects here. After naming, click <strong>OK</strong> button to save category.</p><img loading="lazy" height="95" width="182" class="common_img" src="'+Q+'" style="width:400px;"></li><li><p>Press key <strong>d</strong> to enter next image labeling. After completing labeling for all images, click close button in upper right corner of software to exit.</p></li></ol><h3 id="_6-4-2-data-format-conversion" tabindex="-1">6.4.2 Data Format Conversion <a class="header-anchor" href="#_6-4-2-data-format-conversion" aria-label="Permalink to &quot;6.4.2 Data Format Conversion&quot;">​</a></h3><ul><li><strong>Preparation</strong></li></ul><p>Before starting operations in this section, image collection and labeling must be completed. For detailed operation steps, refer to <a href="#p6-4-1">6.4.1 Image Collection and Labeling</a>.</p><p>Before feeding data into YOLO26 models for training, setting image categories and converting annotation data format must be performed.</p><ul><li><strong>Format Conversion</strong></li></ul><p>Before starting operations in this section, image collection and labeling must be completed.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Command inputs require strict case sensitivity, and the Tab key can be used to complete keywords.</strong></p></div><ol><li>Open a new terminal and enter the command to view the file. <strong>If this file does not exist, create it here.</strong></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gedit ~/my_data/classes.names</span></span></code></pre></div><ol start="2"><li>Write the labeled category <strong>left</strong> into the text file. If multiple different categories exist, edit with line breaks.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Class names added here must strictly match names inside image labeling software &quot;roLabelImg&quot;.</strong></p></div><ol start="3"><li><p>After editing, press the key combination <strong>Ctrl+S</strong> to save and exit.</p></li><li><p>Return to the command line terminal, enter the data format conversion command, and press <strong>Enter</strong>.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ~/third_party_ros2/yolo/xml2yolo_obb.py --data ~/my_data --yaml ~/my_data/data.yaml</span></span></code></pre></div><p>Parameters involved in the command above:</p><ol><li><p><strong>my_data</strong>: Represents the user-labeled folder, and the path needs to correspond.</p></li><li><p><strong>data.yaml</strong>: Represents the format conversion form for the whole folder, saved in the <strong>my_data</strong> folder as seen from the command.</p></li></ol><h3 id="_6-4-3-model-training" tabindex="-1">6.4.3 Model Training <a class="header-anchor" href="#_6-4-3-model-training" aria-label="Permalink to &quot;6.4.3 Model Training&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Command inputs require strict case sensitivity, and the Tab key can be used to complete keywords.</strong></p></div><ul><li><strong>Preparation</strong></li></ul><p>After converting model formats, proceed to model training steps. Before doing so, prepare the dataset converted previously. For details, refer to <a href="#642-data-format-conversion">6.4.2 Data Format Conversion</a>.</p><ul><li><strong>Model Training</strong></li></ul><ol><li><p>Power on the robot and connect it to remote control software VNC.</p></li><li><p>Click the icon <img loading="lazy" height="38" width="46" class="inline-icon" src="'+t+'" style="width:30px;"> on the system desktop to open the command line terminal.</p></li><li><p>Enter the command and press <strong>Enter</strong> to navigate to the specified directory.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/third_party_ros2/yolo/yolo26</span></span></code></pre></div><ol start="5"><li>Enter the model training command and press <strong>Enter</strong>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 train.py --img 640 --batch 64 --epochs 300 --data ~/my_data/data.yaml --weights yolo26n.pt</span></span></code></pre></div><p>In the command, <code>--img</code> represents image dimensions, <code>--batch</code> represents single input image quantity, <code>--epochs</code> represents training iterations, <code>--data</code> represents dataset path, and <code>--weights</code> represents training file path.</p><p>Modify above parameters according to practical needs. To increase model reliability, training iterations can be increased, though training time consumption increases accordingly.</p><p>After model training completes, output path of generated files prints in terminal. Results of this training session save to <strong>/home/ubuntu/runs/detect/train3</strong> directory under home folder.</p><img loading="lazy" height="125" width="1380" class="common_img" src="'+M+'" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Generated file paths are not fixed and can be found inside corresponding folders under runs/detect/train.</strong></p></div><h3 id="_6-4-4-target-detection" tabindex="-1">6.4.4 Target Detection <a class="header-anchor" href="#_6-4-4-target-detection" aria-label="Permalink to &quot;6.4.4 Target Detection&quot;">​</a></h3><p>After extensive training, new models are obtained. For specific operation steps, refer to <a href="#641-image-collection-and-labeling">6.4.1 Image Collection and Labeling</a> through <a href="#643-model-training">6.4.3 Model Training</a>.</p><ul><li><strong>Operation Steps</strong></li></ul><ol><li>Click icon <img loading="lazy" height="38" width="46" class="inline-icon" src="'+t+'" style="width:30px;"> on system desktop to open command line terminal, enter command, and press <strong>Enter</strong> to stop app service.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/.stop_ros.sh</span></span></code></pre></div><ol start="2"><li>Enter command to copy trained <strong>best.pt</strong> file to <strong>~/third_party_ros2/yolo</strong> directory. Paths and filenames of generated files are not fixed and can be modified according to actual situations.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/runs/detect/train3/weights/best.pt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/third_party_ros2/yolo</span></span></code></pre></div><ol start="3"><li>Enter command to open file.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gedit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros2_ws/src/example/example/yolo_detect/yolo_detect_demo.py</span></span></code></pre></div><p>Fill trained model category name <strong>left</strong> into <code>CLASSES_NAMES_DEFAULT</code>, save, and exit. Double quotes &quot; &quot; must be added here.</p><img loading="lazy" height="146" width="782" class="common_img" src="'+j+'" style="width:800px;"><ol start="4"><li>Enter command to run target detection.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yolo_detect_demo.launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model_name:=best</span></span></code></pre></div><ul><li><strong>Detection Effect</strong></li></ul><p>Place target signs within camera field of view. When target signs are recognized, return frames outline signs with bounding boxes, printing category names and detection confidence scores.</p><img loading="lazy" height="487" width="640" class="common_img" src="'+J+'" style="width:600px;"><h2 id="_6-5-waste-card-model" tabindex="-1">6.5 Waste Card Model <a class="header-anchor" href="#_6-5-waste-card-model" aria-label="Permalink to &quot;6.5 Waste Card Model&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Regarding product names and reference paths appearing in documents, subject to actual conditions.</strong></p></div><p>When datasets are large, training on robot controllers is not recommended due to I/O speed and memory constraints resulting in slow training. Utilizing computers equipped with dedicated graphics cards is recommended. Training methods remain identical, requiring only environment configuration for program execution.</p><p>To train custom models, refer to contents of this section for model training.</p><h3 id="_6-5-1-preparation" tabindex="-1">6.5.1 Preparation <a class="header-anchor" href="#_6-5-1-preparation" aria-label="Permalink to &quot;6.5.1 Preparation&quot;">​</a></h3><ol><li><p>Prepare a laptop computer. If using desktop computers, prepare wireless network cards, mice, and other tools.</p></li><li><p>Power on the robotic arm and connect it to remote control software <strong>VNC</strong>. Refer to <a href="https://drive.google.com/drive/folders/1E_TRpBIkzi_glH7KCmwj_b4I6jDOFO-Z?usp=sharing" target="_blank" rel="noreferrer">1. Tutorials / 1. NexArm User Manual / 1.5 Development Environment Setup and Configuration</a>.</p></li></ol><h3 id="_6-5-2-model-usage" tabindex="-1">6.5.2 Model Usage <a class="header-anchor" href="#_6-5-2-model-usage" aria-label="Permalink to &quot;6.5.2 Model Usage&quot;">​</a></h3><ol><li>Click icon <img loading="lazy" height="38" width="46" class="inline-icon" src="'+i+'" style="width:30px;"> on system desktop to open command line terminal.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><ol start="2"><li>Enter command to run target detection.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch example yolo_detect_demo.launch.py model_name:=best_garbage_26</span></span></code></pre></div><ul><li><strong>Detection Effect</strong></li></ul><p>Place signs within camera field of view. When garbage items are recognized, return frames outline items with bounding boxes, printing category names and detection confidence scores.</p><img loading="lazy" height="478" width="596" class="common_img" src="'+X+'" style="width:600px;">',207)])])}const te=o(H,[["render",V]]);export{ie as __pageData,te as default};
